static int rpmsg_eptdev_open(struct inode *inode, struct file *filp)
{
 printk(KERN_INFO "IOCTL_HANDLER: Function rpmsg_eptdev_open called at %s:%d\n", __FILE__, __LINE__);
	struct rpmsg_eptdev *eptdev = cdev_to_eptdev(inode->i_cdev);
	struct rpmsg_endpoint *ept;
	struct rpmsg_device *rpdev = eptdev->rpdev;
	struct device *dev = &eptdev->dev;

	mutex_lock(&eptdev->ept_lock);
	if (eptdev->ept) {
		mutex_unlock(&eptdev->ept_lock);
		return -EBUSY;
	}

	get_device(dev);

	/*
	 * If the default_ept is set, the rpmsg device default endpoint is used.
	 * Else a new endpoint is created on open that will be destroyed on release.
	 */
	if (eptdev->default_ept)
		ept = eptdev->default_ept;
	else
		ept = rpmsg_create_ept(rpdev, rpmsg_ept_cb, eptdev, eptdev->chinfo);

	if (!ept) {
		dev_err(dev, "failed to open %s\n", eptdev->chinfo.name);
		put_device(dev);
		mutex_unlock(&eptdev->ept_lock);
		return -EINVAL;
	}

	eptdev->ept = ept;
	if (eptdev->chinfo.src == RPMSG_ADDR_ANY)
		eptdev->chinfo.src = ept->addr;

	filp->private_data = eptdev;
	mutex_unlock(&eptdev->ept_lock);

	return 0;
}

